function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const r=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('AlphaLab API '+r.status+': '+await r.text());return r.json()}
async function run(input){if(input.confirm_python_execution!==true)throw new Error('Preview requires confirm_python_execution=true');const id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const project=await get('/api/strategy/projects/'+encodeURIComponent(id));const revision=Number(input.revision||project.current_revision);const pkg=await get('/api/strategy/projects/'+encodeURIComponent(id)+'/revisions/'+revision);const response=await fetch(origin()+'/api/strategy/projects/'+encodeURIComponent(id)+'/preview',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({operation:input.operation,profile:input.profile||project.profile,revision,...(input.as_of_date?{as_of_date:input.as_of_date}:{}),confirm_python_execution:true})});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());const result=await response.json();if(result.revision!==revision||result.source_sha256!==pkg.source_sha256)throw new Error('Strategy revision changed during preview');return result}
